package dev.boqing.strongholdplacefix;

import com.mojang.logging.LogUtils;
import net.minecraftforge.fml.common.Mod;
import org.slf4j.Logger;

/**
 * Server-side fix for {@code /place structure minecraft:stronghold <x> <y> <z>}.
 *
 * <p>Vanilla 1.20.1 honours the requested chunk for strongholds, but
 * {@code StructurePiecesBuilder#moveBelowSeaLevel} randomly re-locates the whole
 * structure vertically, so the requested Y is ignored.  While a stronghold is being
 * generated by the place command we replace that random vertical move with one that
 * puts the top of the structure at the requested Y.</p>
 *
 * <p>Natural stronghold generation is untouched: the override only activates while
 * {@link ForcedPlacement} holds a target, which only happens inside the place command.</p>
 */
@Mod(StrongholdPlaceFix.MODID)
public final class StrongholdPlaceFix {
    public static final String MODID = "strongholdplacefix";
    public static final Logger LOGGER = LogUtils.getLogger();

    public StrongholdPlaceFix() {
        LOGGER.info("[strongholdplacefix] loaded: /place structure stronghold now honours the requested Y");
    }
}
